def free_policy_trigger(kind, raw):
    if kind == 'request':
        return ['request_by', ['disclosing_party']]
    if kind == 'agreement_end':
        return ['agreement_termination']
    if kind == 'project_end':
        return ['project_termination']
    if kind == 'relationship_end':
        return ['relationship_termination']
    if kind == 'relationship_nonformation':
        return ['relationship_nonformation_deadline']
    if kind == 'service_end':
        return ['service_termination']
    if kind == 'agreement_end_or_request':
        return ['trigger_alternative', ['agreement_termination'], ['request_by', ['disclosing_party']]]
    if kind == 'project_end_or_request':
        return ['trigger_alternative', ['project_termination'], ['request_by', ['disclosing_party']]]
    if kind == 'relationship_end_or_request':
        return ['trigger_alternative', ['relationship_termination'], ['request_by', ['disclosing_party']]]
    if kind == 'relationship_nonformation_or_request':
        return ['trigger_alternative', ['relationship_nonformation_deadline'], ['request_by', ['disclosing_party']]]
    if kind == 'request_and_affiliate_exit':
        return ['source_stated_trigger', raw]
    return None

def free_policy_action(term):
    material = ['acquired_material_v3', term[5], term[11]]
    if term[3] == 'return':
        return ['return_to', material, ['disclosing_party']]
    if term[3] == 'destroy':
        return ['destroy', material]
    return None

def free_policy_exception(term):
    text = term[11]
    if term[9]:
        text = text + ' ' + term[9]
    if term[10]:
        text = text + ' ' + term[10]
    return ['source_scoped_exception_set', text]

def free_explicit_policy_atom(term):
    if not isinstance(term, list) or len(term) != 12:
        return False
    text = low(term[11])
    if term[3] == 'return' and 'return' not in text:
        return False
    if term[3] == 'destroy' and not has_any(text, ['destroy', 'delete', 'erase']):
        return False
    return has_any(text, ['confidential information', 'such information', 'all information', 'copy', 'copies', 'reproduction', 'materials', 'documents', 'files', 'records'])

def free_compose_acquired_policy(source_output, statements):
    actions = {}
    supports = {}
    links = []
    linked = set()
    for row in compose_rows(source_output):
        if not isinstance(row, dict):
            continue
        term = row.get('term')
        if not isinstance(term, list) or not term:
            continue
        if term[0] == 'acq_disposal_action_v3' and len(term) == 12:
            actions[term[2]] = term
            supports[term[2]] = list(row.get('support_ids', []))
        elif term[0] == 'acq_disposal_link_v3' and len(term) == 6:
            links.append([term, list(row.get('support_ids', []))])
        elif term[0] == 'acq_retention_v3' and len(term) == 7:
            actor = ['receiving_party']
            material = ['source_retention_material', term[6]]
            if term[2] == 'retention_permission':
                norm = ['retention_permission', actor, material, ['after_disposal'], ['retention_condition', term[6]]]
                compose_add(statements, norm, row.get('support_ids', []))
            elif term[2] == 'retention_prohibition':
                norm = ['retention_prohibition', actor, material, ['after_disposal']]
                compose_add(statements, norm, row.get('support_ids', []))
    for link, link_support in links:
        left_id = link[2]
        right_id = link[3]
        left = actions.get(left_id)
        right = actions.get(right_id)
        if left is None or right is None:
            continue
        left_action = free_policy_action(left)
        right_action = free_policy_action(right)
        left_trigger = free_policy_trigger(left[6], left[11])
        right_trigger = free_policy_trigger(right[6], right[11])
        if left_action is None or right_action is None or left_trigger is None or right_trigger is None:
            continue
        left_exception = free_policy_exception(left)
        right_exception = free_policy_exception(right)
        if link[4] == 'and' and left_trigger == right_trigger:
            action = ['action_conjunction', left_action, right_action]
            trigger = left_trigger
        elif link[4] == 'or' and left_trigger == right_trigger:
            action = ['action_alternative', left_action, right_action]
            trigger = left_trigger
        else:
            action = ['conditional_action_alternative_v4', left_action, left_trigger, left_exception, right_action, right_trigger, right_exception, link[5]]
            trigger = ['trigger_alternative', left_trigger, right_trigger]
        exceptions = ['joint_branch_exception_scope_v4', left_exception, right_exception, link[5]]
        support = compose_unique(supports.get(left_id, []) + supports.get(right_id, []) + link_support)
        compose_add(statements, ['disposal_obligation', ['receiving_party'], action, trigger, exceptions], support)
        linked.add(left_id)
        linked.add(right_id)
    for action_id, term in actions.items():
        if action_id in linked or not free_explicit_policy_atom(term):
            continue
        action = free_policy_action(term)
        trigger = free_policy_trigger(term[6], term[11])
        if action is not None and trigger is not None:
            compose_add(statements, ['disposal_obligation', ['receiving_party'], action, trigger, free_policy_exception(term)], supports.get(action_id, []))

def free_clause_context(spans, index):
    start = max(0, index - 2)
    parts = []
    i = start
    while i <= index:
        raw = spans[i].get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        parts.append(raw)
        i += 1
    return ' '.join(parts)

def free_explicit_disclosure_repairs(raw, context, uid, statements):
    text = low(raw)
    whole = low(context)
    if 'confidential information' not in whole:
        return
    employee_clause = has_any(text, ['employees of the receiving party', 'employees of recipient'])
    if employee_clause and has_any(text, ['may disclose', 'may be disclosed']):
        conditions = []
        if has_any(text, ['strictly necessary', 'extent necessary', 'necessary for the permitted purpose']):
            conditions.append(['extent_necessary', raw])
        if has_any(text, ['confidentiality agreement', 'comply with this agreement', 'terms and conditions no less onerous']):
            conditions.append(['confidentiality_bound', raw])
        add_statement(statements, ['permission', ['receiving_party'], ['disclose', ['confidential_information'], ['employees_of', ['receiving_party']]], make_and(conditions)], [uid])
    anyone_prohibition = has_any(text, ['not to disclose it to anyone', 'not disclose it to anyone', 'not to disclose the confidential information to anyone'])
    if anyone_prohibition:
        exceptions = ['exception_set', ['cross_reference_exception', 'disclosure expressly permitted by this Agreement']]
        if has_any(text, ['prior written consent', 'prior written approval']):
            exceptions = ['add_exception', exceptions, ['authorization_exception', 'prior written consent of the other Party']]
        add_statement(statements, ['prohibition', ['receiving_party'], ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], exceptions], [uid])

def apply(inputs, premises):
    source_output = inputs.get('source_output', {})
    statements = []
    unresolved = []
    complete = False
    if isinstance(source_output, dict):
        complete = bool(source_output.get('complete', False))
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                statements.append({'term': row.get('term'), 'support_ids': list(row.get('support_ids', []))})
        for item in source_output.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    free_compose_acquired_disclosures(source_output, statements)
    free_compose_acquired_policy(source_output, statements)
    spans = []
    all_ids = []
    elliptical = False
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
            all_ids.append(span.get('id'))
    i = 0
    while i < len(spans):
        span = spans[i]
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        if free_elliptical_permission(raw, uid, statements):
            elliptical = True
        free_add_disposal_repairs(raw, uid, statements)
        free_explicit_disclosure_repairs(raw, free_clause_context(spans, i), uid, statements)
        i += 1
    if not free_disposal_present(spans):
        add_statement(statements, ['complete_source_no_disposal_obligation'], all_ids)
    if not free_post_disposal_retention_present(spans):
        add_statement(statements, ['complete_source_no_retention_effect'], all_ids)
    if not free_internal_permission_present(spans) and not elliptical and not pb_has_root(statements, 'permission'):
        add_statement(statements, ['complete_source_no_disclosure_permission'], all_ids)
    return {'statements': statements, 'complete': complete and len(unique(unresolved)) == 0, 'unresolved': unique(unresolved)}
